/**
 * A single citation entry, as returned by the AI.
 */
export interface Citation {
  /** Unique citation index, used in <<…>> placeholders */
  index: number;
  /** Identifier or title of the source text */
  textsource: string;
  /** (Optional) Page number within the source */
  page_number?: number;
}


/**
 * TypeScript interfaces matching the above schema:
 */

export interface EnrichedFlashCard {
  term: string;
  definition: string;
}

export interface EnrichedLesson {
  lecture_note: string;
  flash_cards: EnrichedFlashCard[];
}

export interface EnrichedSecondary {
  title: string;
  lecture_note: string;
  flash_cards: EnrichedFlashCard[];
}

export interface MatchingQuestion {
  id: string;
  type: "matching";
  matchingTerm: string;
  matchingAnswer: string;
}

export interface MatchingQuiz {
  id: string;
  title: string;
  questions: MatchingQuestion[];
}

export interface EnrichedPrimary {
  ChronologicalOrder: number;
  title: string;
  lesson: EnrichedLesson;
  secondary_subtopic: EnrichedSecondary[] | null;
  quiz: MatchingQuiz;
  lesson_citation: Citation | null;
}

/** Full batch response shape */
export interface SubtreeBatchResponse {
  primary_subtopics: EnrichedPrimary[];
}
